payload.text:
{"check_build": {"code": "script({
  title: "Pelican on a Bicycle",
  palette: {
    wood: "reddish brown",
    wood_dark: "dark brown",
    wood_light: "tan",
    water: "trans light blue",
    water_deep: "dark blue",
    bike_frame: "dark red",
    bike_metal: "light bluish grey",
    bike_gold: "pearl gold",
    pelican_white: "white",
    pelican_grey: "light bluish grey",
    pelican_dark: "dark bluish grey",
    pouch: "bright light orange",
    beak: "bright light orange",
    feet: "orange",
    cap: "dark blue"
  }
});

// --- SECTION 1: SEASIDE PIER & BOARDWALK ---
const pierOps = [
  // Water base
  floor({ at: [-11, 0, -14], size: [22, 28], colour: "water_deep" }),

  // Sub-structure pier beams
  box({ at: [-9, 1, -12], size: [18, 2, 24], colour: "wood_dark", interior: "fill" }),

  // Pier wooden pilings at corners
  ...[-8, 7].flatMap(x => [-11, 10].map(z => 
    place({ part: "3941.dat", at: [x, 1, z], colour: "wood_dark" })
  )),
  ...[-8, 7].flatMap(x => [-11, 10].map(z => 
    place({ part: "14769.dat", at: [x, 4, z], colour: "wood_dark" })
  )),

  // Wooden boardwalk deck planks (weathered stagger)
  floor({ at: [-8, 3, -11], size: [16, 22], colour: "wood", top: "tile" })
];

// Detail the boardwalk with varied timber planks and mooring bollards
const boardwalkDetails = [
  // Mooring bollards on pier edge
  place({ part: "3941.dat", at: [-7, 4, -8], colour: "wood_dark" }),
  place({ part: "14769.dat", at: [-7, 7, -8], colour: "wood_dark" }),
  place({ part: "3941.dat", at: [6, 4, 6], colour: "wood_dark" }),
  place({ part: "14769.dat", at: [6, 7, 6], colour: "wood_dark" }),

  // Vintage cast-iron lamppost on boardwalk corner
  place({ part: "3941.dat", at: [5, 4, -9], colour: "dark bluish grey" }),
  place({ part: "4032b.dat", at: [5, 7, -9], colour: "black" }),
  ...range(5).map(i => place({ part: "3062b.dat", at: [5, 8 + i * 3, -9], colour: "black" })),
  place({ part: "4032b.dat", at: [5, 23, -9], colour: "black" }),
  place({ part: "3062b.dat", at: [5, 24, -9], colour: "trans-yellow" }),
  place({ part: "4740.dat", at: [5, 27, -9], colour: "black" }),

  // Starfish and sea shell details on edge
  place({ part: "24866.dat", at: [-9, 3, -4], colour: "orange" }),
  place({ part: "98138.dat", at: [-9, 3, 2], colour: "pearl gold" }),
  place({ part: "24866.dat", at: [8, 3, 3], colour: "red" })
];

section("Pier", [...pierOps, ...boardwalkDetails]);

// --- SECTION 2: VINTAGE CRUISER BICYCLE ---
const bikeOps = [
  // Front Wheel (spoked wheel rolling along Z)
  place({ part: "4489a.dat", at: [0, 4, -8], colour: "black", turn: 90 }),
  // Rear Wheel
  place({ part: "4489a.dat", at: [0, 4, 6], colour: "black", turn: 90 }),

  // Front Fork blades flanking the front wheel
  place({ part: "3024.dat", at: [-1, 9, -6], colour: "bike_frame" }),
  place({ part: "3024.dat", at: [1, 9, -6], colour: "bike_frame" }),
  place({ part: "3710.dat", at: [-1, 15, -6], colour: "bike_frame" }), // fork crown

  // Head tube / Steering column
  place({ part: "3062b.dat", at: [0, 16, -6], colour: "bike_frame" }),
  place({ part: "3062b.dat", at: [0, 19, -6], colour: "bike_metal" }),

  // Handlebars
  place({ part: "30031.dat", at: [-1, 22, -6], colour: "black" }),
  // Chrome Headlight
  place({ part: "4081b.dat", at: [0, 19, -7], colour: "light bluish grey" }),
  place({ part: "98138.dat", at: [0, 21, -7], colour: "trans-yellow" }),
  // Pearl gold bell
  place({ part: "98138.dat", at: [1, 23, -6], colour: "pearl gold" }),

  // Front delivery basket mounted to handlebars
  place({ part: "3020.dat", at: [-1, 17, -9], colour: "wood_light" }),
  place({ part: "2412b.dat", at: [-1, 18, -10], colour: "wood_light" }),
  place({ part: "2412b.dat", at: [-1, 18, -8], colour: "wood_light" }),
  place({ part: "64648.dat", at: [0, 19, -9], colour: "sand green" }), // fresh fish in basket!

  // Bottom bracket & Frame tubes
  place({ part: "3022.dat", at: [-1, 8, -1], colour: "bike_frame" }),
  place({ part: "3004.dat", at: [0, 9, -1], colour: "bike_frame" }),

  // Down tube connecting head tube to bottom bracket
  place({ part: "3010.dat", at: [0, 12, -4], colour: "bike_frame" }),
  // Top tube connecting head tube to seat post
  place({ part: "3010.dat", at: [0, 17, -2], colour: "bike_frame" }),
  // Seat tube rising to saddle
  place({ part: "3004.dat", at: [0, 12, 1], colour: "bike_frame" }),
  place({ part: "3004.dat", at: [0, 15, 1], colour: "bike_frame" }),
  place({ part: "3062b.dat", at: [0, 18, 1], colour: "bike_metal" }),

  // Rear chainstays to rear wheel
  place({ part: "3710.dat", at: [0, 9, 2], colour: "bike_frame" }),
  place({ part: "3024.dat", at: [-1, 9, 6], colour: "bike_frame" }),
  place({ part: "3024.dat", at: [1, 9, 6], colour: "bike_frame" }),

  // Rear curved mudguard / fender
  place({ part: "11477.dat", at: [0, 15, 5], colour: "bike_frame", turn: 180 }),
  place({ part: "15068.dat", at: [-1, 15, 7], colour: "bike_frame", turn: 180 }),
  place({ part: "98138.dat", at: [0, 13, 9], colour: "trans-red" }), // rear reflector

  // Leather Saddle
  place({ part: "3022.dat", at: [-1, 20, 1], colour: "wood" }),
  place({ part: "15068.dat", at: [-1, 21, 1], colour: "wood" }),
  place({ part: "11477.dat", at: [0, 21, 0], colour: "wood" }),

  // Pedals & Cranks (left down/forward, right up/backward)
  place({ part: "3024.dat", at: [-2, 6, -2], colour: "bike_metal" }),
  place({ part: "3069b.dat", at: [-2, 7, -2], colour: "black" }), // left pedal
  place({ part: "3024.dat", at: [1, 10, 0], colour: "bike_metal" }),
  place({ part: "3069b.dat", at: [1, 11, 0], colour: "black" })  // right pedal
];

section("Bicycle", bikeOps);

// --- SECTION 3: THE PELICAN ---
const pelicanOps = [
  // Webbed Feet on pedals
  place({ part: "11477.dat", at: [-2, 8, -3], colour: "feet" }),
  place({ part: "11477.dat", at: [1, 12, -1], colour: "feet" }),

  // Legs
  place({ part: "3062b.dat", at: [-2, 11, -2], colour: "feet" }),
  place({ part: "3062b.dat", at: [-2, 14, -1], colour: "feet" }),
  place({ part: "3062b.dat", at: [-2, 17, 0], colour: "feet" }),
  place({ part: "3062b.dat", at: [1, 14, 0], colour: "feet" }),
  place({ part: "3062b.dat", at: [1, 17, 1], colour: "feet" }),

  // Pelican Torso seated on the saddle
  box({ at: [-2, 21, 0], size: [4, 6, 4], colour: "pelican_white", interior: "solid" }),
  box({ at: [-2, 27, -1], size: [4, 6, 4], colour: "pelican_white", interior: "solid" }),

  // Feather shaping - chest (front curved slopes)
  place({ part: "15068.dat", at: [-1, 27, -2], colour: "pelican_white" }),
  place({ part: "11477.dat", at: [-2, 27, -2], colour: "pelican_white" }),
  place({ part: "11477.dat", at: [1, 27, -2], colour: "pelican_white" }),

  // Feather shaping - back and sides
  place({ part: "15068.dat", at: [-1, 27, 3], colour: "pelican_white", turn: 180 }),
  place({ part: "11477.dat", at: [-2, 27, 3], colour: "pelican_white", turn: 180 }),
  place({ part: "11477.dat", at: [1, 27, 3], colour: "pelican_white", turn: 180 }),

  // Tail feathers fan
  place({ part: "11477.dat", at: [-1, 22, 4], colour: "pelican_dark", turn: 180 }),
  place({ part: "11477.dat", at: [0, 22, 4], colour: "pelican_dark", turn: 180 }),

  // Wings folded on sides and reaching forward to the handlebars
  // Left wing
  place({ part: "61678.dat", at: [-3, 27, -2], colour: "pelican_white" }),
  place({ part: "11477.dat", at: [-3, 24, -3], colour: "pelican_grey" }),
  place({ part: "54200.dat", at: [-2, 23, -6], colour: "pelican_dark" }), // wing tip on grip!

  // Right wing
  place({ part: "61678.dat", at: [2, 27, -2], colour: "pelican_white" }),
  place({ part: "11477.dat", at: [2, 24, -3], colour: "pelican_grey" }),
  place({ part: "54200.dat", at: [1, 23, -6], colour: "pelican_dark" }),  // wing tip on grip!

  // Pelican Neck (S-curved forward)
  place({ part: "3004.dat", at: [-1, 33, -2], colour: "pelican_white" }),
  place({ part: "11477.dat", at: [-1, 36, -3], colour: "pelican_white" }),
  place({ part: "11477.dat", at: [0, 36, -3], colour: "pelican_white" }),
  place({ part: "3004.dat", at: [-1, 39, -4], colour: "pelican_white" }),

  // Pelican Head
  box({ at: [-1, 42, -5], size: [3, 4, 3], colour: "pelican_white", interior: "solid" }),
  // Eyes on left and right
  place({ part: "10238.dat", at: [-2, 43, -4], colour: "white", turn: 90 }),
  place({ part: "10238.dat", at: [2, 43, -4], colour: "white", turn: 270 }),

  // Sailor Cap on top of head
  place({ part: "4032b.dat", at: [-1, 46, -5], colour: "cap" }),
  place({ part: "14769.dat", at: [-1, 47, -5], colour: "cap" }),
  place({ part: "98138.dat", at: [0, 48, -5], colour: "pearl gold" }), // cap badge

  // Pelican Upper Beak (long, tapered with hook tip)
  place({ part: "3020.dat", at: [-1, 42, -8], colour: "beak" }),
  place({ part: "11477.dat", at: [0, 43, -9], colour: "beak" }),
  place({ part: "54200.dat", at: [0, 43, -10], colour: "beak" }), // curved hook tip

  // Pelican Elastic Gular Pouch (scooped under the beak)
  place({ part: "24201.dat", at: [-1, 39, -7], colour: "pouch" }),
  place({ part: "24201.dat", at: [0, 39, -7], colour: "pouch" }),
  place({ part: "11477.dat", at: [-1, 36, -6], colour: "pouch" }),
  place({ part: "11477.dat", at: [0, 36, -6], colour: "pouch" }),

  // Fresh fish caught in the pouch (tail sticking out!)
  place({ part: "64648.dat", at: [0, 40, -8], colour: "orange", turn: 180 })
];

section("Pelican", pelicanOps);
", "seed": 1}}

